def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def normalize_name(name: str, classname: str) -> str:
        name = (name or "").strip()
        classname = (classname or "").strip()
        if classname and name:
            if name.startswith(classname):
                return name
            return f"{classname}.{name}"
        return name or classname

    def status_from_testcase(tc: ET.Element) -> str:
        # Child elements
        has_failure = tc.find(".//failure") is not None or tc.find(".//error") is not None
        has_skipped = tc.find(".//skipped") is not None
        if has_failure:
            return "fail"
        if has_skipped:
            return "skip"
        # Attributes
        status_attr = (tc.get("status") or tc.get("result") or "").lower()
        if status_attr in {"skipped", "skip", "notrun", "disabled", "ignored"}:
            return "skip"
        if status_attr in {"fail", "failed", "error", "errors"}:
            return "fail"
        return "pass"

    def parse_xml_block(xml_text: str) -> None:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return

        # Iterate all testcases, handle namespaces
        for tc in root.findall(".//{*}testcase"):
            name = tc.get("name")
            classname = tc.get("classname")
            full_name = normalize_name(name, classname)
            if not full_name:
                continue
            results[full_name] = status_from_testcase(tc)

    # Extract XML blocks that look like JUnit/CTest
    xml_blocks = []
    # Prefer full <testsuites> or <testsuite> blocks
    for pattern in (r"(<testsuites[\s\S]*?</testsuites>)", r"(<testsuite[\s\S]*?</testsuite>)"):
        xml_blocks.extend(re.findall(pattern, log, flags=re.IGNORECASE))
    # If none found, try from first <?xml to end
    if not xml_blocks:
        xml_match = re.search(r"(<\?xml[\s\S]*?>[\s\S]*)", log)
        if xml_match:
            xml_blocks.append(xml_match.group(1))

    for block in xml_blocks:
        parse_xml_block(block)

    # Fallback to text parsing if no results
    if not results:
        # pytest style
        pytest_re = re.compile(r"^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b", re.MULTILINE)
        status_map = {
            "PASSED": "pass",
            "FAILED": "fail",
            "ERROR": "fail",
            "SKIPPED": "skip",
            "XFAIL": "skip",
            "XPASS": "fail",
        }
        for m in pytest_re.finditer(log):
            results[m.group("name")] = status_map[m.group("status")]

        # unittest style
        unittest_re = re.compile(r"^(?P<name>\w+(?:\.\w+)*)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|SKIPPED)\b", re.MULTILINE)
        for m in unittest_re.finditer(log):
            status = m.group("status").lower()
            results[m.group("name")] = "pass" if status == "ok" else ("skip" if status == "skipped" else "fail")

        # Go test
        go_re = re.compile(r"^---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>\S+)", re.MULTILINE)
        for m in go_re.finditer(log):
            status = m.group("status")
            results[m.group("name")] = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}[status]

        # Jest style
        jest_re = re.compile(r"^(?P<symbol>✓|✕|○)\s+(?P<name>.+)$", re.MULTILINE)
        for m in jest_re.finditer(log):
            symbol = m.group("symbol")
            status = "pass" if symbol == "✓" else ("skip" if symbol == "○" else "fail")
            results[m.group("name").strip()] = status

    return results

