def parser(log: str) -> dict[str, str]:
    import json
    import re
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    package_tests: dict[str, set[str]] = defaultdict(set)
    package_failures: set[str] = set()
    current_package: str | None = None

    status_map_go = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}
    status_map_py = {"PASSED": "pass", "FAILED": "fail", "SKIPPED": "skip", "ERROR": "fail"}
    status_map_unittest = {"ok": "pass", "FAIL": "fail", "ERROR": "fail", "skipped": "skip"}

    def record(test: str, status: str, package: str | None = None) -> None:
        if not test:
            return
        name = f"{package}.{test}" if package else test
        results[name] = status
        if package:
            package_tests[package].add(name)

    def parse_go_output(text: str, package: str | None) -> None:
        for match in re.finditer(r"--- (PASS|FAIL|SKIP): ([^ ]+)", text):
            status = status_map_go.get(match.group(1))
            if status:
                record(match.group(2), status, package)

        for match in re.finditer(r"^(FAIL|ok)\s+\t?(\S+)", text, flags=re.MULTILINE):
            pkg = match.group(2)
            nonlocal current_package
            current_package = pkg
            if match.group(1) == "FAIL":
                package_failures.add(pkg)

    for line in log.splitlines():
        raw = line.rstrip("\n")
        if not raw.strip():
            continue

        parsed_json = False
        if raw.lstrip().startswith("{") and raw.rstrip().endswith("}"):
            try:
                event = json.loads(raw)
                parsed_json = True
            except json.JSONDecodeError:
                parsed_json = False

        if parsed_json:
            action = event.get("Action")
            test = event.get("Test")
            package = event.get("Package") or current_package
            if package:
                current_package = package

            if action in ("pass", "fail", "skip") and test:
                record(test, action, package)
            elif action == "output":
                output = event.get("Output", "")
                if output:
                    parse_go_output(output, package)
            elif action == "fail" and not test and package:
                package_failures.add(package)
            continue

        stripped = raw.strip()

        match = re.match(r"--- (PASS|FAIL|SKIP): ([^ ]+)", stripped)
        if match:
            status = status_map_go.get(match.group(1))
            if status:
                record(match.group(2), status, current_package)
            continue

        match = re.match(r"^(FAIL|ok)\s+\t?(\S+)", stripped)
        if match:
            current_package = match.group(2)
            if match.group(1) == "FAIL":
                package_failures.add(current_package)
            continue

        match = re.match(r"^(.+?)::([^\s]+)\s+(PASSED|FAILED|SKIPPED|ERROR)", stripped)
        if match:
            name = f"{match.group(1)}::{match.group(2)}"
            status = status_map_py.get(match.group(3))
            if status:
                results[name] = status
            continue

        match = re.match(r"^(test\w+.*?)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)", stripped, re.IGNORECASE)
        if match:
            test_name = match.group(1).split()[0]
            class_name = match.group(2)
            status = status_map_unittest.get(match.group(3).lower())
            if status:
                results[f"{class_name}.{test_name}"] = status
            continue

        match = re.match(r"^\s*[✓✔]\s+(.*)$", stripped)
        if match:
            results[match.group(1).strip()] = "pass"
            continue

        match = re.match(r"^\s*[✕xX]\s+(.*)$", stripped)
        if match:
            results[match.group(1).strip()] = "fail"
            continue

        match = re.match(r"^\s*[○◯]\s+(.*)$", stripped)
        if match:
            results[match.group(1).strip()] = "skip"
            continue

    if "<testcase" in log and ("</testsuite>" in log or "</testsuites>" in log):
        xml_blocks = re.findall(r"(<testsuite[\s\S]*?</testsuite>|<testsuites[\s\S]*?</testsuites>)", log)
        for block in xml_blocks:
            try:
                root = ET.fromstring(block)
            except ET.ParseError:
                continue
            for testcase in root.iter("testcase"):
                name = testcase.get("name") or ""
                classname = testcase.get("classname")
                full_name = f"{classname}.{name}" if classname else name
                status = "pass"
                if testcase.find("failure") is not None or testcase.find("error") is not None:
                    status = "fail"
                elif testcase.find("skipped") is not None:
                    status = "skip"
                if full_name:
                    results[full_name] = status

    return results

